('dr-meera', 'Dr. Meera Kapoor', 'Pediatrics', 15, 4.98, 700, 'MK', 'peach', 'Gentle, family-centred child care'),
('dr-vikram', 'Dr. Vikram Shah', 'Orthopedics', 11, 4.89, 900, 'VS', 'blue', 'Sports injuries and joint care'),
('dr-sana', 'Dr. Sana Iyer', 'General medicine', 8, 4.94, 500, 'SI', 'rose', 'Everyday health and preventive care'),
('dr-arjun', 'Dr. Arjun Das', 'Neurology', 14, 4.93, 1000, 'AD', 'sand', 'Headache, sleep and neurological care'),
('dr-neha', 'Dr. Neha Kulkarni', 'Gynecology', 10, 4.97, 850, 'NK', 'mint', 'Women''s wellness through every life stage'),
('dr-kabir', 'Dr. Kabir Sethi', 'ENT', 7, 4.88, 600, 'KS', 'lavender', 'Ear, nose and throat consultations') ON DUPLICATE KEY UPDATE name = VALUES(name), specialty = VALUES(specialty), experience = VALUES(experience), rating = VALUES(rating), fee = VALUES(fee), initials = VALUES(initials), color = VALUES(color), about = VALUES(about);

INSERT INTO availability_rules (doctor_id, weekday, start_time, end_time, consultation_minutes)
SELECT d.id, schedule.weekday, schedule.start_time, schedule.end_time, 20
   FROM doctors d
   CROSS JOIN (
     SELECT weekday, '10:00:00' AS start_time, '14:00:00' AS end_time FROM (SELECT 1 AS weekday UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) weekdays
     UNION ALL
     SELECT weekday, '17:00:00' AS start_time, '20:00:00' AS end_time FROM (SELECT 1 AS weekday UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) weekdays
   ) schedule
   WHERE 1 = 1
   ON DUPLICATE KEY UPDATE end_time = VALUES(end_time), consultation_minutes = VALUES(consultation_minutes);

